async function init(){const posts=await (await fetch('data/posts.json')).json();const f=posts.find(x=>x.featured)||posts[0];document.getElementById('hero').innerHTML=`<article class="hero"><a class="heroimg" href="article/${f.slug}.html"><img src="${f.image}" alt=""></a><div><span class="kicker">${f.section} · ${f.type}</span><h1><a href="article/${f.slug}.html">${f.title}</a></h1><p>${f.dek}</p><div class="meta">${f.date} · ${f.author} · ${f.source}</div></div></article>`;document.getElementById('cards').innerHTML=posts.filter(x=>x.id!==f.id).map(p=>`<article class="card"><a class="cardimg" href="article/${p.slug}.html"><img src="${p.image}" alt="" loading="lazy"></a><div><span class="kicker">${p.section} · ${p.type}</span><h2><a href="article/${p.slug}.html">${p.title}</a></h2><p>${p.dek}</p><div class="meta">${p.date} · ${p.author}</div></div></article>`).join('')};document.getElementById('menu').onclick=()=>document.getElementById('nav').classList.toggle('open');init();